13 ; This program uses the two's complement identity x + y == \~(\~x - y)   
14   
15 pull   
16 mov x, \~osr   
17 pull   
18 mov y, osr   
19 jmp test ; this loop is equivalent to the following C code:   
20 incr: ; while (y--)   
21 jmp x-- test ; x--;   
22 test: ; This has the effect of subtracting y from x, eventually.   
23 jmp y-- incr   
24 mov isr, \~x   
